layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: 0.3392px; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 26.6667px; font-weight: 550; font-style: italic; line-height: 1.618; letter-spacing: 2.19358px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background 1s ease-in }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16.96px; font-weight: 400; font-style: normal; line-height: 1.2; letter-spacing: 0.3392px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background 1s ease-in }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 16px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 1; letter-spacing: 0.3392px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2.66667px; padding-right: 6.66667px; padding-bottom: 2.66667px; padding-left: 4px; transition: 0.099s }
